for qid, title, status, owner, question, until, applies, extra in Q:
    meta = {'id': qid, 'title': title, 'summary': re.sub(r'\s*\(\[\[[^\]]*\]\](?:,\s*\[\[[^\]]*\]\])*\)', '', re.sub(r'\[\[NR-([\w-]+)#([\d.]+)\]\]', lambda m: 'п.' + m.group(2) + ' ' + ('892-П' if '892' in m.group(1) else m.group(1)), question)).replace('**', '').replace('[[', '').replace(']]', ''), 'status': status}
    if owner: meta['owner'] = owner
    if applies: meta['applies_to'] = applies
    body = f'**Вопрос.** {question}\n\n'
    if until: body += f'**До решения.** {until}\n\n'
    if extra: body += f'**Решение.** {extra}\n\n' if status == 'закрыт' else extra + '\n\n'
    with open(f'{R}/{qid}.md', 'w', encoding='utf-8') as f:
        f.write('---\n' + yaml.dump(meta, allow_unicode=True, sort_keys=False, width=1000) + '---\n' + body.strip() + '\n')
print(len(Q))
